/* Nearby landmark markers use real coordinates; leader lines separate close pins. */
(()=>{const T=AFRAME.THREE;
AFRAME.registerComponent('nearby-place-pins',{
 init(){this.root=entity('a-entity',{id:'nearbyPlacePins',visible:false},document.getElementById('earthRoot'));this.signature='';this.markers=[];this.lines=[]},
 tick(time){if(time-(this.last||-500)<150)return;this.last=time;const active=window.globiquest.workspace==='explore'&&!window.globiquest.parachutes?.open&&!(typeof featureOpen!=='undefined'&&featureOpen);let data=window.globiquest.nearbyPlaceData?.();if(active&&!data){window.globiquest.ensurePlacePins?.();data=window.globiquest.nearbyPlaceData?.()}this.root.object3D.visible=!!(active&&data?.items?.length);if(!active||!data)return;const entries=data.items.map((item,index)=>({item,index})).filter(({item})=>Number.isFinite(item.lat)&&Number.isFinite(item.lon)&&Math.abs(item.lat)<=90&&Math.abs(item.lon)<=180).slice(0,6),signature=JSON.stringify([data.key,entries.map(({item})=>[item.title,item.lat,item.lon])]);if(signature!==this.signature){this.signature=signature;this.build(data,entries)}for(const pin of this.markers){const chosen=Number(pin.getAttribute('data-nearby-place'))===data.selected;pin.object3D.scale.setScalar(chosen?1.16:1);pin.getObject3D('mesh')?.material?.color?.set(chosen?'#f2bd64':'#ffffff')}this.face(data)},
 clear(){for(const line of this.lines){line.geometry.dispose();line.material.dispose();line.removeFromParent()}this.lines=[];dispose(this.root);this.markers=[];this.label=null},
 build(data,entries){this.clear();const normal=(()=>{const p=mapPoint(data.place[3],data.place[4],1);return new T.Vector3(p.x,p.y,p.z).normalize()})(),orientation=new T.Quaternion().setFromUnitVectors(new T.Vector3(0,0,1),normal),right=new T.Vector3(1,0,0).applyQuaternion(orientation),up=new T.Vector3(0,1,0).applyQuaternion(orientation);this.normal=normal;
  for(const {item,index} of entries){const p=mapPoint(item.lat,item.lon,1.205),anchor=new T.Vector3(p.x,p.y,p.z),slot=this.markers.length,position=normal.clone().multiplyScalar(1.31).addScaledVector(right,(slot%3-1)*.17).addScaledVector(up,(.5-Math.floor(slot/3))*.17),line=new T.Line(new T.BufferGeometry().setFromPoints([anchor,position]),new T.LineBasicMaterial({color:'#c6a65e',transparent:true,opacity:.85}));this.root.object3D.add(line);this.lines.push(line);
   const canvas=document.createElement('canvas');canvas.width=canvas.height=128;const c=canvas.getContext('2d');c.fillStyle=data.selected===index?'#f2bd64':'#e9f6f0';c.beginPath();c.arc(64,64,60,0,Math.PI*2);c.fill();c.strokeStyle='#527268';c.lineWidth=5;c.stroke();c.fillStyle='#253f37';c.textAlign='center';c.font='600 68px Inter, Arial, sans-serif';c.fillText(String(index+1),64,88);const texture=new T.CanvasTexture(canvas);texture.colorSpace=T.SRGBColorSpace;
   const pin=entity('a-circle',{radius:.047,position:`${position.x} ${position.y} ${position.z}`,class:'interactive','data-nearby-place':String(index),'data-canvas':'true','aria-label':'Open '+item.title,material:'shader:flat; side:double'},this.root);pin.object3D.quaternion.copy(orientation);const apply=()=>{const mesh=pin.getObject3D('mesh');if(mesh){mesh.material.map=texture;mesh.material.depthTest=true;mesh.material.depthWrite=true;mesh.material.needsUpdate=true}};window.GlobiquestPanelInput.bind(pin,128,128,[[0,0,128,128,()=>window.globiquest.selectNearbyPlace?.(index,data.key,item.title),'Open '+item.title]]);pin.addEventListener('loaded',apply,{once:true});if(pin.hasLoaded)apply();this.markers.push(pin)
  }
  if(entries.length){const position=normal.clone().multiplyScalar(1.31).addScaledVector(up,-.25),canvas=document.createElement('canvas');canvas.width=1024;canvas.height=150;const c=canvas.getContext('2d');c.fillStyle='rgba(250,253,248,.96)';c.fillRect(0,0,1024,150);c.fillStyle='#29483e';c.textAlign='center';c.font='600 48px Inter, Arial, sans-serif';c.fillText('Nearby places · select a pin',512,60);c.font='400 34px Inter, Arial, sans-serif';c.fillText('Markers spaced for selection',512,116);const map=new T.CanvasTexture(canvas);map.colorSpace=T.SRGBColorSpace;const label=entity('a-plane',{width:.68,height:.10,'data-canvas':'true',position:`${position.x} ${position.y} ${position.z}`,material:'shader:flat; side:double'},this.root);this.label=label;label.object3D.quaternion.copy(orientation);const apply=()=>{const mesh=label.getObject3D('mesh');if(mesh){mesh.material.map=map;mesh.material.needsUpdate=true}};label.addEventListener('loaded',apply,{once:true});if(label.hasLoaded)apply()}
 },
 face(data){const planet=document.getElementById('planet')?.getObject3D('mesh');if(!planet||!this.normal)return;const center=planet.getWorldPosition(new T.Vector3()),head=window.globiquest.xrHeadPose?.()?.position||this.el.camera.getWorldPosition(new T.Vector3()),normal=this.normal.clone().transformDirection(document.getElementById('earthRoot').object3D.matrixWorld);this.root.object3D.visible=this.markers.length>0&&normal.dot(head.clone().sub(center).normalize())>.25;if(this.root.object3D.visible){for(const pin of this.markers)pin.object3D.lookAt(head);this.label?.object3D.lookAt(head)}},
 remove(){this.clear();this.root.remove()}
});const setup=()=>scene.setAttribute('nearby-place-pins','');if(scene.hasLoaded)setup();else scene.addEventListener('loaded',setup,{once:true});})();
